use project;


-- 1.: Total revenue generated by each product

select 
       product_items,
      round(sum(`price per Unit`*`Quantity (liters/kg)`), 2)
as total_revenue from dairy_dataset
group by product_items
order by  total_revenue desc;



--  2.: Give Brand with the highest total revenue

SELECT
    product_items,
    ROUND(SUM(`Price per Unit` * `Quantity (liters/kg)`), 2) AS total_revenue
FROM dairy_dataset
GROUP BY product_items
ORDER BY total_revenue desc limit 1;



-- 3. Give Monthly revenue trend across all products

SELECT
    date_format(`Date`, '%Y-%m') AS revenue_month,
    product_items,
    ROUND(SUM(`Price per Unit` * `Quantity (liters/kg)`), 2) AS total_revenue
FROM dairy_dataset
GROUP BY date_format(`Date`, '%Y-%m'),
product_items
ORDER BY revenue_month,
product_items ;



-- 4. Products below the minimum stock threshold

select product_items,
`Quantity in Stock (liters/kg)` AS Quantity_in_stock,
`Minimum Stock Threshold (liters/kg)` AS Minimum_stock_threshold
 from dairy_dataset
WHERE `Quantity in Stock (liters/kg)` < `Minimum Stock Threshold (liters/kg)`
ORDER BY `Quantity in Stock (liters/kg)`;


-- 5.. Total reorder quantity required per product

-- 5. Total reorder quantity required per product

SELECT
    product_items,
    ROUND(SUM(`Reorder Quantity (liters/kg)`), 2) AS total_reorder_quantity
FROM dairy_dataset
GROUP BY product_items
ORDER BY total_reorder_quantity DESC;

-- 6. Which sales channel generates the most revenue

SELECT
    `Sales Channel`,
    ROUND(SUM(`Price per Unit` * `Quantity (liters/kg)`), 2) AS total_revenue
FROM dairy_dataset
GROUP BY `Sales Channel`
ORDER BY total_revenue desc limit 1;

-- 7. Top 5 customer locations by purchase volume

select 
 `Customer Location` AS Customer_location,
round(sum(`Quantity Sold (liters/kg)`)) AS Total_volume_purchase
from dairy_dataset
group by `Customer Location`
order by Total_volume_purchase desc limit 5;

-- 8. Average selling price per product

select
product_items,
round(avg(`Price per Unit (sold)`), 2) AS Average_product_price
 from dairy_dataset
 group by product_items
 order by Average_product_price;


-- 9. Compare selling price with listed price

select
`product_items`,
round(avg(`Price per Unit`),2) AS Average_listed_price,
round(avg(`Price per Unit (sold)`),2) AS Average_Selling_price,
round(avg(`Price per Unit (sold)`)-avg(`Price per Unit`),2) AS Price_difference
from dairy_dataset
group by `product_items`
order by `product_items`;

-- 10. Products with less than 10 days shelf life remaining

select
product_items,
datediff(`Expiration Date`,'2023-11-01') AS Days_remaining
from dairy_dataset
where datediff(`Expiration Date`,'2023-11-01') <10
   AND datediff(`Expiration Date`,'2023-11-01')>=0
order by Days_remaining;   


-- 12. Average number of cows per farm size category

select
`Farm Size`,
round(avg(`Number of Cows`),2) AS average_no_cows
from dairy_dataset
group by `Farm Size`
order by average_no_cows;

-- 13. Location with the largest total land area
select 
location,
round(sum(`Total Land Area (acres)`),2) AS Total_land_area
from dairy_dataset
group by location
order by Total_land_area DESC limit 1;
-- 14. Top 3 locations by average production quantity

select 
location,
round(avg(`Quantity (liters/kg)`),2) AS average_production_quantity
from dairy_dataset
group by location 
order by average_production_quantity desc limit 3;

-- 15. Calculate profit for each product

select
product_items,
round(sum(`Approx. Total Revenue(INR)`)- sum(`Total Value`), 2) AS  profit
from dairy_dataset
group by product_items
order by profit desc;

-- 16. Most profitable brand overall

select
product_items,
round(sum(`Approx. Total Revenue(INR)`)- sum(`Total Value`), 2) AS  profit
from dairy_dataset
group by product_items
order by profit desc limit 1;

-- Q11: Average shelf life by product category

SELECT
    product_items,
    ROUND(AVG(`Shelf Life (days)`), 2) AS average_shelf_life_days
FROM dairy_dataset
GROUP BY product_items
ORDER BY average_shelf_life_days DESC;











-- Q21: Average shelf life per brand

SELECT
    Brand,
    ROUND(AVG(`Shelf Life (days)`), 2) AS average_shelf_life_days
FROM dairy_dataset
GROUP BY Brand
ORDER BY average_shelf_life_days DESC;



-- Q20: Expired products still in stock

SELECT
    product_items,
    `Expiration Date`,
    `Quantity in Stock (liters/kg)` AS quantity_in_stock
FROM dairy_dataset
WHERE `Expiration Date` < CURDATE()
  AND `Quantity in Stock (liters/kg)` > 0
ORDER BY `Expiration Date`;

-- Q19: Products that need immediate restock

SELECT
    product_items,
    `Quantity in Stock (liters/kg)` AS quantity_in_stock,
    `Minimum Stock Threshold (liters/kg)` AS minimum_stock_threshold,
    `Reorder Quantity (liters/kg)` AS reorder_quantity
FROM dairy_dataset
WHERE `Quantity in Stock (liters/kg)`
      <= `Minimum Stock Threshold (liters/kg)`
ORDER BY `Quantity in Stock (liters/kg)`;


WITH product_sales AS (
    SELECT
        `Customer Location` AS customer_location,
        product_items,
        SUM(`Quantity Sold (liters/kg)`) AS total_quantity_sold,
        ROW_NUMBER() OVER (
            PARTITION BY `Customer Location`
            ORDER BY SUM(`Quantity Sold (liters/kg)`) DESC
        ) AS rank_no
    FROM dairy_dataset
    GROUP BY `Customer Location`, product_items
)
SELECT
    customer_location,
    product_items,
    total_quantity_sold
FROM product_sales
WHERE rank_no = 1
ORDER BY customer_location;



-- Q22: Most popular product in each customer location

SELECT
    `Customer Location` AS customer_location,
    product_items,
    ROUND(total_quantity_sold, 2) AS total_quantity_sold
FROM (
    SELECT
        `Customer Location`, product_items,  total_quantity_sold,
        ROW_NUMBER() OVER (
            PARTITION BY `Customer Location`
            ORDER BY total_quantity_sold DESC
        ) AS product_rank
    FROM (
        SELECT
            `Customer Location`,product_items,
            SUM(`Quantity Sold (liters/kg)`) AS total_quantity_sold
        FROM dairy_dataset
        GROUP BY `Customer Location`, product_items
    ) AS location_sales
) AS ranked_products
WHERE product_rank = 1
ORDER BY customer_location;





-- Q17: Yearly revenue growth

SELECT
    sales_year,
    ROUND(total_revenue, 2) AS total_revenue,
    ROUND(
        total_revenue - LAG(total_revenue) OVER (ORDER BY sales_year),
        2
    ) AS revenue_growth
FROM (
    SELECT
        YEAR(`Date`) AS sales_year,
        SUM(`Approx. Total Revenue(INR)`) AS total_revenue
    FROM dairy_dataset
    GROUP BY YEAR(`Date`)
) AS yearly_revenue
ORDER BY sales_year;


-- Q18: Best-selling product each year

SELECT
    sales_year,
    product_items,
    ROUND(total_quantity_sold, 2) AS total_quantity_sold
FROM (
    SELECT
        sales_year,
        product_items,
        total_quantity_sold,
        ROW_NUMBER() OVER (
            PARTITION BY sales_year
            ORDER BY total_quantity_sold DESC
        ) AS sales_rank
    FROM (
        SELECT
            YEAR(`Date`) AS sales_year,
            product_items,
            SUM(`Quantity Sold (liters/kg)`) AS total_quantity_sold
        FROM dairy_dataset
        GROUP BY YEAR(`Date`), product_items
    ) AS yearly_sales
) AS ranked_sales
WHERE sales_rank = 1
ORDER BY sales_year;



